def check_password(input_pwd, secret):
    # Return number of matching characters from the start
    for i, (a, b) in enumerate(zip(input_pwd, secret)):
        if a != b:
            return i
    return min(len(input_pwd), len(secret))

def crack_password(secret):
    guessed = ''
    # We don't know the length, but we can keep going until no improvement
    while len(guessed) < len(secret):  # In real attack, we'd not know len; we stop when full match?
        best_char = ''
        best_count = len(guessed)  # baseline is matching prefix length
        for c in 'abcdefghijklmnopqrstuvwxyz':
            trial = guessed + c
            count = check_password(trial, secret)
            if count > best_count:
                best_count = count
                best_char = c
        if best_char:
            guessed += best_char
        else:
            # Couldn't extend, maybe we reached end or error
            break
        if guessed == secret:
            break
    return guessed
